import type { ChatMessageInput, SummaryPreprocessRule } from "../../shared/domain";
import { applySummaryPreprocess } from "./preprocess-core";

interface WorkerRequest {
  messages: ChatMessageInput[];
  rules: SummaryPreprocessRule[];
}

self.addEventListener("message", (event: MessageEvent<WorkerRequest>) => {
  try {
    self.postMessage({ ok: true, messages: applySummaryPreprocess(event.data.messages, event.data.rules) });
  } catch (error) {
    self.postMessage({ ok: false, error: error instanceof Error ? error.message : String(error) });
  }
});
